const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n||0);const clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;const minutes=s=>{const[a,b]=s.split(':').map(Number);return a*60+b};
const paths={agenda:'M4 5h16v15H4zM4 10h16M8 3v4M16 3v4M8 14h2M14 14h2',students:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 7M22 21v-2a4 4 0 0 0-3-4',groups:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 8v6M15 11h6',rental:'M3 19 15 3M8 21 20 5M3 16l5 4M15 4l5 4',sectors:'m2 20 7-15 5 10 4-7 5 12zM6 12l3 2 3-2',instructors:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 21v-2a6 6 0 0 1 6-5h4a6 6 0 0 1 6 5v2',fees:'M5 3h14v18l-3-2-4 2-4-2-3 2zM8 8h8M8 12h5',metrics:'M4 20V4M4 20h17M8 16v-5M13 16V7M18 16v-8',wind:'M3 8h12a3 3 0 1 0-3-3M3 12h16a3 3 0 1 1-3 3M3 16h6',plus:'M12 5v14M5 12h14',chev:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',close:'M6 6l12 12M18 6 6 18',check:'m5 12 4 4L19 6',refresh:'M20 7v5h-5M4 17v-5h5M19 12a7 7 0 0 0-12-5L4 10M5 12a7 7 0 0 0 12 5l3-3',clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',logout:'M10 4H4v16h6M10 12h12M18 8l4 4-4 4',list:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',menu:'M3 6h18M3 12h18M3 18h18',chat:'M21 11a9 9 0 0 1-9 9H4l-3 2 1-6a9 9 0 1 1 19-5M7 8h10M7 12h7',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const logo=`<svg width="37" height="34" viewBox="0 0 50 43" aria-hidden="true"><path d="M2 38 18 6 29 26 36 13 49 38Z" fill="none" stroke="currentColor" stroke-width="3.2"/><path d="m12 18 6 4 5-4" fill="none" stroke="currentColor" stroke-width="2"/></svg>`;
let db,session,profile,day='2026-08-14',page='agenda',view='grid',discipline='',data={},requestKeys=new Map();const cfg=window.COTA_CONFIG||{};const demo=!cfg.url;let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
async function rest(path,body,method){if(session&&session.expires_at<Date.now()+30000){const r=await fetch(`${cfg.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:cfg.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok){logout();throw Error('La sesión venció. Volvé a ingresar.')}const s=await r.json();session={...s,expires_at:Date.now()+s.expires_in*1000};sessionStorage.setItem('cota.session',JSON.stringify(session))}const r=await fetch(`${cfg.url}${path}`,{method:method||(body?'POST':'GET'),headers:{apikey:cfg.key,Authorization:`Bearer ${session?.access_token||cfg.key}`,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw Error(j.message||j.msg||j.error_description||'No pudimos guardar. Actualizá los datos.');return j}
async function rpc(name,args={}){if(!demo)return rest('/rest/v1/rpc/'+name,args);const functions={validate_class:['select validate_class($1::jsonb,$2::uuid) as result',[JSON.stringify(args.p),args.exclude_class_id||null]],mutate:['select mutate($1,$2::jsonb,$3::uuid) as result',[args.action,JSON.stringify(args.p),args.request_id]],wind_options:['select wind_options($1::uuid) as result',[args.cid]],family_text:['select family_text($1::uuid) as result',[args.cid]],financial_day:['select financial_day($1::date) as result',[args.d]],payment_states:['select payment_states($1::date) as result',[args.d]],quote_class:['select quote_class($1::jsonb) as result',[JSON.stringify(args.p)]]};const [sql,params]=functions[name];return(await db.query(sql,params)).rows[0].result}
async function read(table){if(table==='classes')table='class_board';const rows=demo?(await db.query(`select * from ${table}`)).rows:await rest('/rest/v1/'+table+'?select=*');return rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,v instanceof Date?(k==='day'||k==='birth_date'?v.toISOString().slice(0,10):v.toISOString()):v]))).sort((a,b)=>(a.id||'').localeCompare(b.id||''))}
async function load(){const names=['instructors','sectors','students','classes','enrollments','availability','closures'];if(profile.role!=='instructor')names.push('products','prices','rentals');const rows=await Promise.all(names.map(read));data=Object.fromEntries(names.map((n,i)=>[n,rows[i]]));if(profile.role!=='instructor')data.payments=await rpc('payment_states',{d:day});if(profile.role==='coordinacion')data.finance=(await rpc('financial_day',{d:day})).classes;render()}
const rows=()=>data.classes.filter(c=>c.day===day).sort((a,b)=>a.start_min-b.start_min);const by=(t,id)=>data[t]?.find(x=>x.id===id)||{};const roster=c=>data.enrollments.filter(e=>e.class_id===c.id&&e.status==='confirmada');const waiting=c=>data.enrollments.filter(e=>e.class_id===c.id&&e.status==='espera').sort((a,b)=>a.created_at.localeCompare(b.created_at));const active=c=>c.status!=='cancelada';const can=()=>profile.role!=='instructor';const coord=()=>profile.role==='coordinacion';
const typeName=t=>({exclusiva:'Exclusiva',semi:'Semi exclusiva',grupal:'Grupal'}[t]);const sport=s=>s==='esqui'?'Esquí':'Snowboard';const stat=s=>({programada:'Programada',confirmada:'Confirmada',en_curso:'En curso',dictada:'Dictada',afectada_viento:'Afectada por viento',cancelada:'Cancelada'}[s]||s);const review=c=>c.needs_review===true;const badge=c=>`<span class="badge ${c.status==='afectada_viento'?'orange':c.status==='dictada'?'green':c.status==='cancelada'?'gray':''}">${review(c)?'Por revisar':stat(c.status)}</span>`;
const nav=[['agenda','Agenda diaria'],['students','Alumnos'],['groups','Grupales'],['rental','Alquileres'],['sectors','Sectores y viento'],['instructors','Instructores'],['fees','Honorarios'],['metrics','Jornada']];
function render(){const permitted=nav.filter(([p])=>profile.role==='instructor'?p==='agenda':coord()||!['fees','metrics'].includes(p));if(!permitted.some(([p])=>p===page))page='agenda';$('#app').innerHTML=`<aside class="sidebar"><div class="brand">${logo}<div>COTA<small>ESCUELA DE NIEVE</small></div></div><div class="navcap">OPERACIÓN DIARIA</div>${permitted.slice(0,4).map(navItem).join('')}${can()?'<div class="navcap">EL CERRO</div>':''}${permitted.slice(4,6).map(navItem).join('')}${coord()?'<div class="navcap">CIERRE DE JORNADA</div>':''}${permitted.slice(6).map(navItem).join('')}<div class="sidefoot"><div class="season">TEMPORADA 2026 · ARGENTINA</div><div class="profile"><span class="avatar">${profile.name.slice(0,1)}</span><div><b style="font-size:11px">${esc(profile.name)}</b><div class="sub">${{coordinacion:'Coordinación',recepcion:'Recepción',instructor:'Instructor'}[profile.role]}</div></div><button class="quiet iconbtn" title="${demo?'Ingreso Supabase':'Cerrar sesión'}" data-act="logout" style="color:#c6dce9;margin-left:auto">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><button class="quiet iconbtn mobilemenu" data-act="menu" aria-label="Abrir menú">${icon('menu')}</button><div class="crumb">Operación <span style="padding:0 12px">/</span> <b>${nav.find(n=>n[0]===page)[1]}</b></div><div class="topright">${demo?'<span class="demo">DEMO LOCAL · DATOS SINTÉTICOS</span>':'<span class="online"><i class="dot"></i> Supabase conectado</span>'}<span style="color:var(--muted);font-size:11px">${icon('sectors')} Base del cerro</span><button class="iconbtn quiet" data-act="refresh" title="Actualizar datos">${icon('refresh')}</button></div></header><main class="content">${head()}${({agenda:agenda,students:studentsPage,groups:groupsPage,rental:rentalPage,sectors:sectorsPage,instructors:instructorsPage,fees:feesPage,metrics:metricsPage}[page])()}${page==='rental'&&coord()?priceSettings():''}<footer class="footer"><span>COTA · Operación de escuela de nieve</span><span>${demo?'Datos de prueba · Se guardan solo en este navegador':'Montos en pesos argentinos · Temporada 2026'}</span></footer></main></div>`;bind()}
function navItem([p,n]){return`<button class="navbutton ${page===p?'active':''}" data-page="${p}">${icon(p)}${n}</button>`}
function datebar(){return`<div class="datebar"><button data-act="prev" aria-label="Día anterior">${icon('left')}</button><label class="datepick"><span>${day.split('-').reverse().join('/')}</span><input id="day" aria-label="Fecha de la jornada" type="date" value="${day}"></label><button data-act="next" aria-label="Día siguiente">${icon('chev')}</button></div>`}
function head(){const titles={agenda:['PARTE DE OPERACIONES','Agenda diaria','Cada clase en su lugar. El cerro, bajo control.'],students:['LA ESCUELA','Alumnos','Fichas, niveles e inscripciones. Todo a mano.'],groups:['INSCRIPCIONES','Clases grupales','Ocho lugares por clase. Un grupo por fecha.'],rental:['EQUIPAMIENTO','Alquileres','Stock por día, sin reservas que se pisen.'],sectors:['PARTE DE PISTAS','Sectores y viento','Abierto, cerrado y qué clases hay que reubicar.'],instructors:['EL EQUIPO','Instructores','Habilitaciones, idiomas y disponibilidad.'],fees:['CIERRE DE JORNADA','Honorarios','Solo se liquidan las clases dictadas.'],metrics:['CIERRE DE JORNADA','Cómo rindió el día','La jornada en números claros.']};const [k,t,s]=titles[page];return`<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${s}</p></div><div class="btnline">${page!=='students'&&page!=='instructors'?datebar():''}${can()&&page==='agenda'?`<button class="primary" data-act="newclass">${icon('plus')} Nueva clase</button>`:page==='students'?`<button class="primary" data-act="newstudent">${icon('plus')} Nuevo alumno</button>`:page==='rental'?`<button class="primary" data-act="newrental">${icon('plus')} Reservar equipo</button>`:''}</div></div>`}
function kpi(label,value,sub,ico,cls=''){return`<div class="kpi">${icon(ico)}<label>${label}</label><div class="value ${cls}">${value}</div><small>${sub}</small></div>`}
function agenda(){const cs=rows(),live=cs.filter(active),aff=cs.filter(c=>c.status==='afectada_viento'),n=live.reduce((a,c)=>a+roster(c).length,0),inUse=new Set(live.map(c=>c.instructor_id)).size;return`<div class="kpis">${kpi('Clases del día',live.length,`${cs.filter(c=>c.status==='dictada').length} dictadas · ${live.filter(c=>c.status!=='dictada').length} por delante`,'agenda')}${kpi('Alumnos en pista',n,'Inscripciones confirmadas','students')}${kpi('Instructores asignados',`${inUse}<span style="font-size:17px;color:#92a3ae"> / ${data.instructors.length}</span>`,'30 min de margen entre clases','instructors')}${kpi('Clases por resolver',aff.length,aff.length?'Afectadas por cierre de sector':'Todo listo para salir','wind',aff.length?'accent':'')}</div>${aff.length?`<div class="alert">${icon('wind')}<p><strong>Filo Alto cerrado por viento.</strong> ${aff.length===1?'Una clase necesita un nuevo lugar.':aff.length+' clases necesitan un nuevo lugar.'} Revisá las opciones antes de salir.</p><button data-page="sectors">Resolver clases ${icon('chev')}</button></div>`:''}<section class="panel"><div class="panelhead"><div><h2>${new Intl.DateTimeFormat('es-AR',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(day+'T12:00Z')).replace(/^./,s=>s.toUpperCase())}</h2><small>Horario de montaña · 08:00 a 18:00</small></div><div class="segmented"><button data-view="grid" class="${view==='grid'?'selected':''}">${icon('agenda')} Grilla</button><button data-view="list" class="${view==='list'?'selected':''}">${icon('list')} Lista</button></div></div><div class="filterbar"><div class="legend"><span><i class="ex"></i>Exclusiva</span><span><i class="se"></i>Semi exclusiva</span><span><i class="gr"></i>Grupal</span></div><select id="sportfilter" aria-label="Filtrar disciplina"><option value="">Todas las disciplinas</option value="esqui" ${discipline==='esqui'?'selected':''}>Esquí</option><option value="snowboard" ${discipline==='snowboard'?'selected':''}>Snowboard</option></select></div>${view==='grid'?timeline(cs):classTable(cs.filter(c=>!discipline||c.discipline===discipline))}<div class="panelnote">${icon('info')} Las franjas rayadas reservan 30 min para descanso y traslado. No suman horas de clase.</div></section><div class="bottomgrid"><section class="panel"><div class="panelhead"><h2>Estado de los sectores</h2>${can()?'<button class="quiet" data-page="sectors" style="min-height:25px;padding:0;font-size:10px">Ver parte →</button>':''}</div><div class="sectorstrip">${data.sectors.map(s=>sectorPill(s)).join('')}</div></section><section class="panel"><div class="panelhead"><h2>Grupales del día</h2>${can()?'<button class="quiet" data-page="groups" style="min-height:25px;padding:0;font-size:10px">Ver inscripciones →</button>':''}</div>${cs.filter(c=>c.type==='grupal').map(c=>`<div class="groupmini"><div><b>${clock(c.start_min)} · ${sport(c.discipline)} · Nivel ${c.level}</b><span>${esc(by('instructors',c.instructor_id).name)} · ${esc(by('sectors',c.sector_id).name)}</span></div><div><b>${roster(c).length} / 8 <span>alumnos</span></b><div class="progress"><i style="width:${roster(c).length/8*100}%"></i></div><span>${review(c)?'Por revisar':8-roster(c).length+' lugares libres'}</span></div></div>`).join('')||'<div class="empty">No hay grupales para esta fecha.</div>'}</section></div>`}
function timeline(cs){return`<div class="timeline-scroll"><div class="timeline"><div class="hours"><span>INSTRUCTOR / DISCIPLINA</span><div class="ruler">${Array.from({length:11},(_,i)=>`<span style="left:${i*10}%">${8+i}:00</span>`).join('')}</div></div>${data.instructors.map(i=>{const lessons=cs.filter(c=>c.instructor_id===i.id&&(!discipline||discipline===c.discipline));return`<div class="track"><div class="instructor"><span class="avatar">${i.name.split(' ').map(s=>s[0]).join('')}</span><div><b>${esc(i.name)}</b><small>${i.disciplines.map(sport).join(' / ')}</small></div></div><div class="lane">${data.availability.filter(a=>a.instructor_id===i.id&&a.day===day).map(a=>`<div class="unavailable" style="left:${(a.start_min-480)/6}%;width:${(a.end_min-a.start_min)/6}%">${esc(a.reason)}</div>`).join('')}${lessons.filter(active).map(c=>`<div class="buffer" title="30 minutos de margen" style="left:${(c.start_min+c.duration-480)/6}%;width:${Math.min(30,1080-c.start_min-c.duration)/6}%"></div>`).join('')}${lessons.map(c=>`<button class="lesson ${c.type} ${c.status}" data-class="${c.id}" aria-label="${esc(typeName(c.type)+' '+i.name+' '+clock(c.start_min))}" style="left:${(c.start_min-480)/6}%;width:calc(${c.duration/6}% - 5px)"><b>${clock(c.start_min)} – ${clock(c.start_min+c.duration)} <span style="display:inline;float:right;margin:0">${c.status==='dictada'?'✓':''}</span></b><span>${typeName(c.type)} · ${roster(c).length} alumnos</span><em>${c.status==='afectada_viento'?'⚑ Reubicar · ':''}${esc(by('sectors',c.sector_id).name)}</em></button>`).join('')}</div></div>`}).join('')}</div></div>`}
function classTable(cs){return`<div class="tablewrap"><table class="lessonlist"><thead><tr><th>Horario</th><th>Clase</th><th>Instructor</th><th>Sector</th><th>Estado</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><b>${clock(c.start_min)} – ${clock(c.start_min+c.duration)}</b></td><td>${typeName(c.type)}<br><small>${sport(c.discipline)} · Nivel ${c.level} · ${roster(c).length} alumnos</small></td><td>${esc(by('instructors',c.instructor_id).name)}</td><td>${esc(by('sectors',c.sector_id).name)}</td><td>${badge(c)}</td><td><button data-class="${c.id}">Ver clase</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay clases en esta fecha.</td></tr>'}</tbody></table></div>`}
function sectorPill(s){const closed=data.closures.find(c=>c.sector_id===s.id&&c.day===day&&c.active);return`<div class="sectorpill ${closed?'closed':''}"><b>${esc(s.name)}</b><span><i class="dot"></i>${closed?'Cerrado · viento':s.indoor?'Refugio disponible':'Abierto'} · ${s.capacity} lugares</span></div>`}
function studentsPage(){return`<div class="panel"><div class="panelhead"><h2>${data.students.length} alumnos de prueba</h2><input id="search" class="search" placeholder="Buscar alumno…" aria-label="Buscar alumno"></div><div class="tablewrap"><table><thead><tr><th>Alumno</th><th>Nivel</th><th>Edad</th><th>Clases confirmadas</th><th></th></tr></thead><tbody id="studentrows">${studentRows('')}</tbody></table></div></div>`}
function studentRows(q){return data.students.filter(s=>s.name.toLowerCase().includes(q.toLowerCase())).map(s=>`<tr><td><b>${esc(s.name)}</b><br><small>${esc(s.phone)||'Sin celular · ficha sintética'}</small></td><td><span class="badge">Nivel ${s.level}</span><br><small>${['','Primera vez','Giro controlado','Pistas azules','Pistas rojas y técnica'][s.level]}</small></td><td>${Math.floor((new Date(day)-new Date(s.birth_date))/31557600000)} años</td><td>${data.enrollments.filter(e=>e.student_id===s.id&&e.status==='confirmada').length}</td><td><button data-student="${s.id}">Ver ficha</button></td></tr>`).join('')}
function groupsPage(){const groups=rows().filter(c=>c.type==='grupal');return`<div class="btnline" style="margin-bottom:20px"><button class="primary" data-act="newgroup">${icon('plus')} Abrir grupal de esta fecha</button><small>10:00 a 12:00 · Mayores de 15 años · $65.000 por persona</small></div><div class="cards">${groups.map(c=>`<article class="card"><h3>${sport(c.discipline)} ${badge(c)}</h3><p>${clock(c.start_min)} a ${clock(c.start_min+c.duration)} · Nivel ${c.level}<br>${esc(by('instructors',c.instructor_id).name)}<br>${esc(by('sectors',c.sector_id).name)}</p><div class="big">${roster(c).length}<span class="sub"> / 8 lugares</span></div><div class="bar"><span style="width:${roster(c).length/8*100}%"></span></div><p>${waiting(c).length} en espera · ${review(c)?'Menos de 3: coordinación debe resolver':'Mínimo 3 para abrir'}</p><div class="btnline"><button class="primary" data-enroll="${c.id}">${roster(c).length>=8?'Completo · Lista de espera':'Inscribir alumno'}</button><button data-class="${c.id}">Ver clase</button></div>${review(c)&&coord()?`<button data-merge="${c.id}" style="margin-top:12px">Fusionar con otra grupal</button>`:''}</article>`).join('')||'<div class="empty full"><h3>La grupal de hoy empieza acá</h3><p>Abrí una clase para esta fecha y sumá las inscripciones.</p></div>'}</div>`}
function rentalPage(){const rs=(data.rentals||[]).filter(r=>r.day===day);return`<div class="cards" style="margin-bottom:23px">${data.products.map(p=>{const used=rs.filter(r=>r.product_id===p.id&&r.status==='reservado').reduce((a,r)=>a+r.quantity,0);return`<div class="card"><h3 style="font-size:14px">${esc(p.name)}${icon('rental')}</h3><div class="big">${p.stock-used}<span class="sub"> / ${p.stock} disponibles</span></div><div class="bar"><span style="width:${used/p.stock*100}%"></span></div><small>${money(p.price)} por día</small>${coord()?`<button data-config="product:${p.id}" style="margin-top:14px">Editar precio y stock</button>`:''}</div>`}).join('')}</div><section class="panel"><div class="panelhead"><h2>Reservas de equipo</h2><small>El stock se libera al cancelar</small></div><div class="tablewrap"><table><thead><tr><th>Alumno</th><th>Equipo</th><th>Cantidad</th><th>Estado</th><th>Registro de cobro</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(by('students',r.student_id).name)}</td><td>${esc(by('products',r.product_id).name)}</td><td>${r.quantity}</td><td>${r.status}</td><td><button data-rentalpay="${r.id}">${r.payment==='pagado'?'✓ Pagado':'Pendiente'}</button></td><td>${r.status==='reservado'?`<button data-rentalcancel="${r.id}">Cancelar reserva</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Todavía no hay equipos reservados.</td></tr>'}</tbody></table></div></section>`}
function sectorsPage(){const aff=rows().filter(c=>c.status==='afectada_viento');return`<div class="cards">${data.sectors.map(s=>{const close=data.closures.find(c=>c.sector_id===s.id&&c.day===day&&c.active);return`<div class="card"><h3>${esc(s.name)} ${icon(s.wind_sensitive?'wind':'sectors')}</h3><p>Niveles ${s.levels.join(', ')} · Cupo simultáneo ${s.capacity}<br>${s.indoor?'Techada · Calentamiento y días sin pista':s.wind_sensitive?'Expuesto al viento':'Sector protegido'}</p><span class="badge ${close?'orange':'green'}">${close?`Cerrado ${clock(close.start_min)} a ${clock(close.end_min)}`:'Abierto'}</span>${coord()?`<button data-config="sector:${s.id}" style="margin-top:14px">Editar cupo</button>`:''}${coord()&&s.wind_sensitive?`<div style="margin-top:17px"><button ${close?`data-reopen="${close.id}"`:`data-wind="${s.id}"`} class="${close?'':'danger'}">${close?'Reabrir sector':'Cerrar por viento'}</button></div>`:''}</div>`}).join('')}</div><section class="panel" style="margin-top:24px"><div class="panelhead"><div><h2>Clases para reubicar</h2><small>Otro sector → Aula Refugio → Otro horario con el mismo instructor</small></div><span class="badge ${aff.length?'orange':''}">${aff.length} pendientes</span></div>${classTable(aff)}<div class="panelnote">Aceptá o descartá cada propuesta. La disponibilidad se vuelve a validar antes de guardar.</div></section>`}
function instructorsPage(){return`<div class="cards">${data.instructors.map(i=>`<article class="card"><div class="btnline" style="margin-bottom:18px"><span class="avatar">${i.name.split(' ').map(s=>s[0]).join('')}</span><h3 style="margin:0">${esc(i.name)}</h3></div><p>${i.disciplines.map(sport).join(' / ')} · Hasta nivel ${i.max_level}<br>${i.languages.map(l=>({es:'Español',en:'Inglés',pt:'Portugués'}[l])).join(' · ')}</p><div class="rulelist"><span>${icon('clock')} Tope diario: ${i.max_hours} horas</span><span>Día libre: ${i.days_off.map(n=>['domingo','lunes','martes','miércoles','jueves','viernes','sábado'][n]).join(', ')||'Sin día fijo'}</span></div>${coord()?`<div class="btnline" style="margin-top:17px"><button data-unavailable="${i.id}">No disponible</button><button data-config="instructor:${i.id}">Editar ficha</button></div>`:''}</article>`).join('')}</div>`}
function feesPage(){const fs=data.finance||[],done=fs.filter(c=>c.status==='dictada'),total=done.reduce((a,f)=>a+Number(f.fee),0);return`<div class="kpis">${kpi('Honorarios de la jornada',money(total),'Calculados sobre clases dictadas','fees')}${kpi('Clases liquidadas',done.length,'Excluye canceladas y pendientes','check')}${kpi('Horas dictadas',done.reduce((a,f)=>a+Number(f.hours),0),'Día completo = 5 h efectivas','clock')}${kpi('Asistencias grupales',data.enrollments.filter(e=>e.present&&done.some(c=>c.class_id===e.class_id&&c.type==='grupal')).length,'$18.000 por alumno presente','students')}</div><section class="panel"><div class="panelhead"><h2>Liquidación por instructor</h2><small>Exclusiva 35% · Semi 30% · Grupal por asistencia</small></div><div class="tablewrap"><table><thead><tr><th>Instructor</th><th>Clases dictadas</th><th>Horas efectivas</th><th>Honorarios</th></tr></thead><tbody>${data.instructors.map(i=>{const ds=done.filter(c=>c.instructor_id===i.id);return`<tr><td><b>${esc(i.name)}</b></td><td>${ds.length}</td><td>${ds.reduce((a,c)=>a+Number(c.hours),0)} h</td><td><b>${money(ds.reduce((a,c)=>a+Number(c.fee),0))}</b></td></tr>`}).join('')}</tbody></table></div></section>`}
function metricsPage(){const fs=data.finance||[],live=fs.filter(c=>c.status!=='cancelada'),cancel=fs.filter(c=>c.status==='cancelada'),groups=rows().filter(c=>c.type==='grupal'&&active(c)),enrolled=groups.reduce((a,c)=>a+roster(c).length,0);return`<div class="kpis">${kpi('Facturación de clases',money(live.reduce((a,c)=>a+c.amount,0)),'Precio acordado · Excluye canceladas','metrics')}${kpi('Cobrado registrado',money(live.filter(c=>c.payment==='pagado').reduce((a,c)=>a+c.amount,0)),'Registro manual, sin pagos reales','fees')}${kpi('Ocupación de grupales',groups.length?Math.round(enrolled/(groups.length*8)*100)+'%':'—',`${enrolled} inscriptos / ${groups.length*8} lugares`,'groups')}${kpi('Cancelaciones',fs.length?Math.round(cancel.length/fs.length*100)+'%':'—',`${cancel.length} de ${fs.length} clases`,'agenda')}</div><div class="bottomgrid"><section class="panel"><div class="panelhead"><h2>Facturación por tipo</h2></div><div class="metricrows">${['exclusiva','semi','grupal'].map(t=>{const a=live.filter(c=>c.type===t).reduce((a,c)=>a+c.amount,0);return`<div><b>${typeName(t)}</b><progress value="${a}" max="${Math.max(1,...['exclusiva','semi','grupal'].map(t=>live.filter(c=>c.type===t).reduce((a,c)=>a+c.amount,0)))}"></progress><span>${money(a)}</span></div>`}).join('')}</div></section><section class="panel"><div class="panelhead"><h2>Cancelaciones por motivo</h2></div>${cancel.length?`<div class="metricrows">${[...new Set(cancel.map(c=>c.cancel_reason))].map(r=>`<div><b>${esc(r)}</b><progress value="${cancel.filter(c=>c.cancel_reason===r).length}" max="${cancel.length}"></progress><span>${Math.round(cancel.filter(c=>c.cancel_reason===r).length/cancel.length*100)}%</span></div>`).join('')}</div>`:'<div class="empty">Sin cancelaciones en esta jornada.</div>'}</section></div><section class="panel"><div class="panelhead"><h2>Horas dictadas por instructor</h2></div><div class="metricrows">${data.instructors.map(i=>{const h=fs.filter(c=>c.instructor_id===i.id&&c.status==='dictada').reduce((a,c)=>a+Number(c.hours),0);return`<div><b>${esc(i.name)}</b><progress value="${h}" max="6"></progress><span>${h} / 6 h</span></div>`}).join('')}</div></section>`}
function openModal(title,body,foot=''){const m=$('#modal');m.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="quiet iconbtn" data-close aria-label="Cerrar">${icon('close')}</button></div><div class="modalbody">${body}<div id="actionerror" class="validation" role="alert"></div></div>${foot?`<div class="modalfoot">${foot}</div>`:''}`;if(!m.open)m.showModal();m.querySelector('[data-close]').onclick=()=>m.close();bind(m);return m}
const options=(arr,selected,label)=>arr.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(label(x))}</option>`).join('');
function field(label,content,full=false){return`<div class="field ${full?'full':''}"><label>${label}</label>${content}</div>`}
async function action(a,p,button){const error=$('#actionerror');if(button)button.disabled=true;const key=JSON.stringify([a,p]);if(!requestKeys.has(key))requestKeys.set(key,crypto.randomUUID());try{const r=await rpc('mutate',{action:a,p,request_id:requestKeys.get(key)});if(r.errors?.length){showErrors(r.errors);return null}await load();requestKeys.delete(key);return r}catch(e){if(error){error.innerHTML=`${esc(e.message)}<div><button id="refreshConflict" style="margin-top:10px">Actualizar datos</button></div>`;$('#refreshConflict').onclick=async()=>{await load();$('#modal').close();toast('Datos actualizados. Volvé a abrir la acción.')};error.scrollIntoView({block:'nearest'})}else toast(e.message);return null}finally{if(button)button.disabled=false}}
function showErrors(errors){const el=$('#actionerror');el.className='validation';el.innerHTML=`<b>Revisá antes de guardar</b><ul>${errors.map(e=>`<li>${esc(e.message)}</li>`).join('')}</ul><button id="refreshConflict">Actualizar datos</button>`;$('#refreshConflict').onclick=async()=>{await load();el.innerHTML='Datos actualizados. Volvé a validar antes de confirmar.'}}
function classForm(c=null,type='exclusiva'){const selected=c?roster(c).map(e=>e.student_id):[];const val=(key,def)=>c?.[key]??def;openModal(c?'Editar clase':'Nueva clase',`<div class="eyebrow" style="margin-bottom:17px">PROPUESTA → VALIDACIÓN → CONFIRMACIÓN</div><form id="classform"><div class="fields">${field('Tipo de clase',`<select name="type" aria-label="Tipo de clase">${['exclusiva','semi','grupal'].map(t=>`<option value="${t}" ${val('type',type)===t?'selected':''}>${typeName(t)}</option>`).join('')}</select>`)}${field('Disciplina',`<select name="discipline" aria-label="Disciplina" ${c?'disabled':''}><option value="esqui" ${c?.discipline==='esqui'?'selected':''}>Esquí</option><option value="snowboard" ${c?.discipline==='snowboard'?'selected':''}>Snowboard</option></select>`)}${field('Fecha',`<input name="day" type="date" aria-label="Fecha" required value="${val('day',day)}">`)}${field('Hora de inicio',`<input name="start" type="time" aria-label="Hora de inicio" required value="${clock(val('start_min',600))}" step="1800">`)}${field('Duración',`<select name="duration" aria-label="Duración"></select>`)}${field('Idioma',`<select name="language" aria-label="Idioma">${[['es','Español'],['en','Inglés'],['pt','Portugués']].map(([v,l])=>`<option value="${v}" ${c?.language===v?'selected':''}>${l}</option>`).join('')}</select>`)}${field('Nivel de la clase',`<select name="level" aria-label="Nivel de la clase" ${c?'disabled':''}>${[1,2,3,4].map(n=>`<option value="${n}" ${val('level',1)===n?'selected':''}>Nivel ${n}</option>`).join('')}</select><span class="help">Con alumnos, se toma el nivel más alto.</span>`)}${field('Instructor',`<select name="instructor_id" aria-label="Instructor"></select>`)}${field('Sector',`<select name="sector_id" aria-label="Sector">${options(data.sectors,c?.sector_id,s=>`${s.name} · N${s.levels.join('/')} · ${s.capacity} lugares`)}</select>`,true)}${field('Alumnos',`<div class="studentsel">${data.students.map(s=>`<label class="checkrow"><input type="checkbox" name="students" value="${s.id}" ${selected.includes(s.id)?'checked':''}>${esc(s.name)} <small>N${s.level}</small></label>`).join('')}</div><span class="help">Exclusiva 1–3 · Semi 4–6 · Grupal 0–8 (mínimo 3 para abrir)</span>`,true)}</div></form><div class="quote"><span>Precio de la clase <small>· ARS 2026</small></span><b id="quote">—</b></div>`,`<button id="validate">${icon('check')} Validar propuesta</button><button class="primary" id="saveclass">Confirmar clase</button>`);
 const f=$('#classform');function get(){const fd=new FormData(f);return {day:fd.get('day'),start_min:minutes(fd.get('start')),duration:Number(fd.get('duration')),type:fd.get('type'),discipline:c?.discipline||fd.get('discipline'),language:fd.get('language'),level:c?.level||Number(fd.get('level')),instructor_id:fd.get('instructor_id'),sector_id:fd.get('sector_id'),student_ids:fd.getAll('students'),...(c?{class_id:c.id,version:c.version}:{})}}
 function durations(){const t=f.elements.type.value;f.elements.duration.innerHTML=data.prices.filter(p=>p.type===t).map(p=>`<option value="${p.duration}" ${p.duration===c?.duration?'selected':''}>${p.duration===360?'Día completo · 5 h + almuerzo':p.duration/60+' horas'}</option>`).join('');if(t==='grupal'||Number(f.elements.duration.value)===360)f.elements.start.value='10:00'}
 function instructors(){const p=get(),levels=data.students.filter(s=>p.student_ids.includes(s.id)).map(s=>s.level),max=Math.max(p.level,...levels);const prev=f.elements.instructor_id.value||c?.instructor_id;f.elements.instructor_id.innerHTML='<option value="">Elegí un instructor</option>'+options(data.instructors.filter(i=>i.disciplines.includes(p.discipline)&&i.max_level>=max&&i.languages.includes(p.language)),prev,i=>`${i.name} · N${i.max_level}`)}
 async function quote(){try{$('#quote').textContent=money(await rpc('quote_class',{p:get()}))}catch{$('#quote').textContent='—'}}
 f.onchange=async e=>{if(e.target.name==='type')durations();if(['discipline','language','level','students','type'].includes(e.target.name))instructors();if(Number(f.elements.duration.value)===360)f.elements.start.value='10:00';$('#actionerror').innerHTML='';await quote()};durations();instructors();quote();
 $('#validate').onclick=async()=>{try{const errors=await rpc('validate_class',{p:get(),exclude_class_id:c?.id||null});if(errors.length)showErrors(errors);else{$('#actionerror').className='validation good';$('#actionerror').textContent='Todo en orden. Instructor, sector y horario disponibles.'}}catch(e){showErrors([{message:e.message}])}};
 $('#saveclass').onclick=async e=>{if(!f.reportValidity())return;const r=await action('save_class',get(),e.currentTarget);if(r){$('#modal').close();toast('Clase confirmada. Ya está en la agenda.');await detail(r.id)}};
}
async function detail(cid){const c=by('classes',cid);if(!c.id)return;const enroll=roster(c),wait=waiting(c);openModal(`${typeName(c.type)} · ${sport(c.discipline)}`,`${badge(c)}<div class="detailgrid"><div><small>Horario</small><b>${c.day.split('-').reverse().join('/')} · ${clock(c.start_min)} a ${clock(c.start_min+c.duration)}</b></div><div><small>Instructor</small><b>${esc(by('instructors',c.instructor_id).name)}</b></div><div><small>Sector</small><b>${esc(by('sectors',c.sector_id).name)}</b></div><div><small>Nivel / idioma</small><b>Nivel ${c.level} · ${{es:'Español',en:'Inglés',pt:'Portugués'}[c.language]}</b></div></div><h3>Alumnos confirmados · ${enroll.length}</h3>${enroll.map(e=>`<div class="checkrow" style="justify-content:space-between"><span>${esc(by('students',e.student_id).name)} <small>· Nivel ${by('students',e.student_id).level}</small></span>${can()&&c.type==='grupal'&&active(c)&&c.status!=='dictada'?`<button data-cancelenroll="${e.id}" style="min-height:28px;padding:4px 8px;font-size:10px">Quitar</button>`:''}</div>`).join('')||'<p class="sub">Todavía no hay alumnos.</p>'}${wait.length?`<h3 style="margin-top:20px">Lista de espera</h3>${wait.map((e,i)=>`<p class="sub">${i+1}. ${esc(by('students',e.student_id).name)} ${e.notification?`<button data-notice="${e.id}">Compartir aviso</button>`:''}</p>`).join('')}`:''}${can()&&data.enrollments.some(e=>e.class_id===c.id&&e.notification)?`<button id="notices" style="margin-top:15px">Ver avisos de promoción</button>`:''}${c.duration===360?'<p class="sub">5 horas de clase. Almuerzo de 13:00 a 14:00.</p>':''}${can()?`<div class="quote"><span>Registro de cobro</span><button id="classpay">${data.payments?.find(f=>f.class_id===c.id)?.payment==='pagado'?'✓ Pagado':'Pendiente'}</button></div>`:''}`,`<div class="btnline">${can()&&c.status!=='dictada'&&active(c)?`<button id="editclass">Editar</button><button class="danger" id="cancelclass">Cancelar clase</button>`:''}</div><div class="btnline">${c.status==='confirmada'&&can()?'<button id="startclass">Iniciar</button>':''}${can()?`<button id="sharefamily">${icon('chat')} WhatsApp</button>`:''}${['confirmada','en_curso'].includes(c.status)?`<button class="primary" id="dictateclass">Marcar dictada</button>`:c.status==='afectada_viento'&&can()?'<button id="relocate" class="primary">Buscar reubicación</button>':''}</div>`);
 $('#startclass')?.addEventListener('click',async e=>{if(await action('start',{class_id:c.id,version:c.version},e.currentTarget)){toast('Clase en curso.');detail(c.id)}});$('#editclass')?.addEventListener('click',()=>classForm(c));$('#sharefamily')?.addEventListener('click',async()=>share(await rpc('family_text',{cid:c.id})));$('#relocate')?.addEventListener('click',()=>windOptions(c));$('#cancelclass')?.addEventListener('click',()=>cancelClass(c));$('#dictateclass')?.addEventListener('click',()=>dictate(c));$('#classpay')?.addEventListener('click',async e=>{const payment=data.payments?.find(f=>f.class_id===c.id)?.payment==='pagado'?'pendiente':'pagado';if(await action('payment',{class_id:c.id,version:c.version,payment},e.currentTarget)){toast('Registro de cobro actualizado');detail(c.id)}});
 document.querySelectorAll('[data-cancelenroll]').forEach(b=>b.onclick=async()=>{if(await action('cancel_enrollment',{class_id:c.id,version:c.version,enrollment_id:b.dataset.cancelenroll},b)){toast('Inscripción cancelada. Revisá los avisos de la lista de espera.');detail(c.id)}});
 $('#notices')?.addEventListener('click',()=>{const ns=data.enrollments.filter(e=>e.class_id===c.id&&e.notification);openModal('Avisos a las familias',ns.map(e=>`<div class="windopt"><div><b>${esc(by('students',e.student_id).name)}</b><p class="sub">${esc(e.notification)}</p></div><button data-notice="${e.id}">${icon('chat')} Compartir</button></div>`).join(''));bindNotices()});bindNotices();}
function bindNotices(){document.querySelectorAll('[data-notice]').forEach(b=>b.onclick=()=>share(by('enrollments',b.dataset.notice).notification))}
function share(text){window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')}
function cancelClass(c){openModal('Cancelar clase',`<p>Se liberan el instructor, el sector y los equipos asociados. Las inscripciones quedan canceladas.</p>${field('Motivo','<select id="cancelreason" aria-label="Motivo"><option>Viento</option><option>Pedido de la familia</option><option>Falta de alumnos</option><option>Fusión</option><option>Otro</option></select>')}`,'<button data-back>Volver</button><button class="danger" id="confirmcancel">Cancelar y liberar recursos</button>');$('[data-back]').onclick=()=>detail(c.id);$('#confirmcancel').onclick=async e=>{if(await action('cancel_class',{class_id:c.id,version:c.version,reason:$('#cancelreason').value},e.currentTarget)){$('#modal').close();toast('Clase cancelada. Recursos liberados.')}}}
function dictate(c){openModal('Cerrar clase y registrar asistencia',`<p class="sub">Marcá quiénes estuvieron presentes. Al confirmar, la clase queda dictada y ya no se edita.</p>${roster(c).map(e=>`<label class="checkrow"><input type="checkbox" name="present" value="${e.student_id}" checked>${esc(by('students',e.student_id).name)}</label>`).join('')}`,'<button id="dictate" class="primary">Confirmar clase dictada</button>');$('#dictate').onclick=async e=>{const present_ids=[...document.querySelectorAll('[name="present"]:checked')].map(i=>i.value);if(await action('dictate',{class_id:c.id,version:c.version,present_ids},e.currentTarget)){$('#modal').close();toast('Clase dictada. Asistencia registrada.')}}}
function studentForm(){openModal('Nuevo alumno',`<form id="studentform" class="fields">${field('Nombre de prueba','<input name="name" aria-label="Nombre" required placeholder="Ej. Alex Nival">',true)}${field('Fecha de nacimiento','<input name="birth_date" aria-label="Fecha de nacimiento" type="date" required>')}${field('Nivel','<select name="level" aria-label="Nivel"><option value="1">1 · Primera vez</option><option value="2">2 · Giro controlado</option><option value="3">3 · Pistas azules</option><option value="4">4 · Pistas rojas</option></select>')}${field('Celular de prueba (opcional)','<input name="phone" aria-label="Celular" placeholder="No cargues datos personales reales">',true)}</form>`,'<small>Usá únicamente datos sintéticos.</small><button id="savestudent" class="primary">Crear alumno</button>');$('#savestudent').onclick=async e=>{const f=$('#studentform');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));if(await action('student',p,e.currentTarget)){$('#modal').close();toast('Alumno creado. Ya podés inscribirlo.')}}}
function enrollForm(c){openModal(roster(c).length>=8?'Sumar a lista de espera':'Inscribir en grupal',`<p>${sport(c.discipline)} · ${clock(c.start_min)} · Nivel ${c.level}</p>${field('Alumno',`<select id="enrollstudent" aria-label="Alumno">${options(data.students.filter(s=>!data.enrollments.some(e=>e.class_id===c.id&&e.student_id===s.id&&e.status!=='cancelada')),null,s=>`${s.name} · Nivel ${s.level}`)}</select>`)}<p class="sub">${roster(c).length>=8?'La clase está completa. La inscripción entra en espera por orden de llegada.':'Se verifica el cupo y la compatibilidad antes de confirmar.'}</p>`,`<button class="primary" id="confirmenroll">${roster(c).length>=8?'Anotar en espera':'Confirmar inscripción'}</button>`);$('#confirmenroll').onclick=async e=>{const r=await action('enroll',{class_id:c.id,version:c.version,student_id:$('#enrollstudent').value},e.currentTarget);if(r){$('#modal').close();toast(r.waiting?'Alumno anotado en lista de espera.':'Inscripción confirmada.');detail(c.id)}}}
function rentalForm(){openModal('Reservar equipo',`<form id="rentalform" class="fields">${field('Alumno',`<select name="student_id" aria-label="Alumno">${options(data.students,null,s=>s.name)}</select>`,true)}${field('Equipo',`<select name="product_id" aria-label="Equipo">${options(data.products,null,p=>`${p.name} · ${money(p.price)}/día`)}</select>`,true)}${field('Fecha',`<input type="date" name="day" aria-label="Fecha" required value="${day}">`)}${field('Cantidad','<input type="number" name="quantity" aria-label="Cantidad" min="1" max="40" value="1" required>')}${field('Asociar a una clase (opcional)',`<select name="class_id" aria-label="Clase"><option value="">Alquiler independiente</option>${options(rows().filter(c=>active(c)&&c.status!=='dictada'),null,c=>`${clock(c.start_min)} · ${typeName(c.type)} · ${by('instructors',c.instructor_id).name}`)}</select>`,true)}</form><p class="sub">El stock se valida y reserva en una sola operación. El cobro se registra manualmente.</p>`,'<button class="primary" id="saverental">Confirmar reserva</button>');$('#saverental').onclick=async e=>{const f=$('#rentalform');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));p.quantity=Number(p.quantity);if(!p.class_id)delete p.class_id;else p.version=by('classes',p.class_id).version;if(await action('rent',p,e.currentTarget)){$('#modal').close();toast('Equipo reservado. Stock actualizado.')}}}
function rentalState(id,cancel){const r=by('rentals',id);openModal(cancel?'Cancelar alquiler':'Registrar cobro del alquiler',`<p>${esc(by('products',r.product_id).name)} · ${r.quantity} unidad(es)<br>${esc(by('students',r.student_id).name)}</p><p class="sub">${cancel?'Se devuelve el equipo al stock de esta fecha.':'Es un registro manual. No se procesa ningún pago.'}</p>`,`<button id="rentalstate" class="${cancel?'danger':'primary'}">${cancel?'Cancelar y liberar stock':r.payment==='pagado'?'Marcar pendiente':'Marcar pagado'}</button>`);$('#rentalstate').onclick=async e=>{const p={rental_id:id,rental_version:r.version,...(cancel?{status:'cancelado'}:{payment:r.payment==='pagado'?'pendiente':'pagado'})};if(await action('rental_state',p,e.currentTarget)){$('#modal').close();toast(cancel?'Reserva cancelada. Stock liberado.':'Cobro registrado.')}}}
function windForm(s){openModal('Cerrar sector por viento',`<p><b>${esc(s.name)}</b> · Las clases de la franja pasan a afectadas por viento.</p><form id="windform" class="fields">${field('Desde','<input name="start" type="time" aria-label="Desde" value="09:00" required>')}${field('Hasta','<input name="end" type="time" aria-label="Hasta" value="17:00" required>')}</form>`,'<button class="danger" id="closewind">Cerrar sector y revisar clases</button>');$('#closewind').onclick=async e=>{const f=$('#windform');if(!f.reportValidity())return;const p={day,sector_id:s.id,start_min:minutes(f.elements.start.value),end_min:minutes(f.elements.end.value)};if(await action('wind',p,e.currentTarget)){$('#modal').close();toast('Sector cerrado. Revisá las clases afectadas.')}}}
async function windOptions(c){openModal('Opciones de reubicación','<p>Buscando sectores y horarios compatibles…</p>');try{const opts=await rpc('wind_options',{cid:c.id});let i=0;function show(){if(i>=opts.length){openModal('Reubicar clase','<div class="empty"><h3>Queda para resolver a mano</h3><p>No hay más opciones válidas para este día. La clase sigue afectada por viento.</p></div>','<button id="manualedit">Editar propuesta</button>');$('#manualedit').onclick=()=>classForm(c);return}const o=opts[i];openModal('Reubicar clase',`<div class="eyebrow">PROPUESTA ${i+1} DE ${opts.length}</div><div class="windopt" style="margin-top:18px"><div><b>${esc(o.label)}</b><small>${esc(by('instructors',c.instructor_id).name)} · ${clock(o.start_min)} a ${clock(o.start_min+c.duration)}<br>${roster(c).length} alumnos · Nivel ${c.level}</small></div><span class="badge green">Compatible</span></div><p class="sub">Primero otro sector en el mismo horario; luego el refugio y, por último, otro horario. Al aceptar se vuelve a validar con la agenda actual.</p>`,`<button id="discardoption">Descartar propuesta</button><button class="primary" id="acceptoption">Aceptar reubicación</button>`);$('#discardoption').onclick=()=>{i++;show()};$('#acceptoption').onclick=async e=>{const r=await action('relocate',{class_id:c.id,version:c.version,sector_id:o.sector_id,start_min:o.start_min},e.currentTarget);if(r){toast('Clase reubicada. Ya podés avisar a la familia.');detail(c.id)}}}show()}catch(e){$('#actionerror').textContent=e.message}}
function mergeForm(c){const targets=rows().filter(t=>t.id!==c.id&&t.type==='grupal'&&t.discipline===c.discipline&&['programada','confirmada'].includes(t.status));openModal('Fusionar grupales',`<p class="sub">Se trasladan las inscripciones y la espera. El grupo de origen se cancela con motivo Fusión.</p>${field('Grupal destino',`<select id="mergetarget" aria-label="Grupal destino">${options(targets,null,t=>`${sport(t.discipline)} · Nivel ${t.level} · ${roster(t).length}/8 · ${by('instructors',t.instructor_id).name}`)}</select>`)}`,'<button id="confirmmerge" class="primary">Validar y fusionar</button>');$('#confirmmerge').onclick=async e=>{const t=by('classes',$('#mergetarget').value);if(await action('merge',{class_id:c.id,version:c.version,target_id:t.id,target_version:t.version},e.currentTarget)){$('#modal').close();toast('Grupales fusionadas. Revisá el aviso a las familias.')}}}
function unavailableForm(i){openModal('Bloque no disponible',`<p><b>${esc(i.name)}</b></p><form id="unavailableform" class="fields">${field('Fecha',`<input name="day" aria-label="Fecha" type="date" value="${day}" required>`,true)}${field('Desde','<input type="time" name="start" aria-label="Desde" value="14:00" required>')}${field('Hasta','<input type="time" name="end" aria-label="Hasta" value="16:00" required>')}${field('Motivo','<input name="reason" aria-label="Motivo" required placeholder="Ej. Capacitación">',true)}</form>`,'<button id="saveunavailable" class="primary">Guardar bloqueo</button>');$('#saveunavailable').onclick=async e=>{const f=$('#unavailableform');if(!f.reportValidity())return;const fd=new FormData(f);if(await action('availability',{instructor_id:i.id,day:fd.get('day'),start_min:minutes(fd.get('start')),end_min:minutes(fd.get('end')),reason:fd.get('reason')},e.currentTarget)){$('#modal').close();toast('Bloque no disponible guardado.')}}}
function priceSettings(){return `<section class="panel"><div class="panelhead"><h2>Tarifas de clases · Temporada 2026</h2><small>No cambia el precio ya acordado de las clases existentes</small></div><div class="tablewrap"><table><thead><tr><th>Tipo</th><th>Duración</th><th>Precio base</th><th></th></tr></thead><tbody>${data.prices.map(p=>`<tr><td>${typeName(p.type)}</td><td>${p.duration===360?'Día completo':p.duration/60+' h'}</td><td>${money(p.price)}</td><td><button data-config="price:${p.type}-${p.duration}">Editar tarifa</button></td></tr>`).join('')}</tbody></table></div></section>`}
function configure(entity,id){let p={entity,id},fields='';if(entity==='product'){const x=by('products',id);fields=field('Precio diario',`<input name="price" aria-label="Precio diario" type="number" min="0" value="${x.price}" required>`)+field('Stock total',`<input name="stock" aria-label="Stock total" type="number" min="0" value="${x.stock}" required>`)}if(entity==='sector'){const x=by('sectors',id);fields=field('Cupo simultáneo de alumnos',`<input name="capacity" aria-label="Cupo simultáneo" type="number" min="1" value="${x.capacity}" required>`,true)}if(entity==='price'){const[t,d]=id.split('-');const x=data.prices.find(x=>x.type===t&&x.duration===Number(d));p={entity,type:t,duration:Number(d)};fields=field('Precio base ARS',`<input name="price" aria-label="Precio base" type="number" min="0" value="${x.price}" required>`,true)}if(entity==='instructor'){const x=by('instructors',id);fields=field('Nombre',`<input name="name" aria-label="Nombre" value="${esc(x.name)}" required>`,true)+field('Disciplina',`<select name="discipline" aria-label="Disciplina"><option value="esqui" ${x.disciplines.join()==='esqui'?'selected':''}>Esquí</option><option value="snowboard" ${x.disciplines.join()==='snowboard'?'selected':''}>Snowboard</option><option value="ambas" ${x.disciplines.length===2?'selected':''}>Ambas</option></select>`)+field('Nivel máximo',`<input name="max_level" aria-label="Nivel máximo" type="number" min="1" max="4" value="${x.max_level}" required>`)+field('Tope de horas diario',`<input name="max_hours" aria-label="Tope de horas" type="number" min="1" max="6" value="${x.max_hours}" required>`)+field('Día libre',`<select name="days_off" aria-label="Día libre">${['domingo','lunes','martes','miércoles','jueves','viernes','sábado'].map((d,n)=>`<option value="${n}" ${x.days_off.includes(n)?'selected':''}>${d}</option>`).join('')}</select>`)+field('Idiomas',`<div class="btnline"><label class="checkrow"><input type="checkbox" checked disabled>Español</label>${[['pt','Portugués'],['en','Inglés']].map(([v,l])=>`<label class="checkrow"><input name="languages" type="checkbox" value="${v}" ${x.languages.includes(v)?'checked':''}>${l}</label>`).join('')}</div>`,true)}openModal('Configuración · Coordinación',`<form id="configform" class="fields">${fields}</form><p class="sub">El cambio se rechaza si deja una clase sin habilitación o un stock por debajo de lo reservado.</p>`,'<button id="saveconfig" class="primary">Guardar configuración</button>');$('#saveconfig').onclick=async e=>{const f=$('#configform');if(!f.reportValidity())return;const fd=new FormData(f);let values=Object.fromEntries(fd);if(entity==='instructor'){values.disciplines=values.discipline==='ambas'?['esqui','snowboard']:[values.discipline];delete values.discipline;values.languages=['es',...fd.getAll('languages')];values.days_off=[Number(values.days_off)]}if(await action('configure',{...p,...values},e.currentTarget)){$('#modal').close();toast('Configuración guardada.')}}}
function bind(root=document){root.querySelectorAll('[data-config]').forEach(b=>b.onclick=()=>configure(...b.dataset.config.split(':')));root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});root.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>detail(b.dataset.class));root.querySelectorAll('[data-enroll]').forEach(b=>b.onclick=()=>enrollForm(by('classes',b.dataset.enroll)));root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});root.querySelectorAll('[data-wind]').forEach(b=>b.onclick=()=>windForm(by('sectors',b.dataset.wind)));root.querySelectorAll('[data-unavailable]').forEach(b=>b.onclick=()=>unavailableForm(by('instructors',b.dataset.unavailable)));root.querySelectorAll('[data-merge]').forEach(b=>b.onclick=()=>mergeForm(by('classes',b.dataset.merge)));root.querySelectorAll('[data-rentalpay]').forEach(b=>b.onclick=()=>rentalState(b.dataset.rentalpay,false));root.querySelectorAll('[data-rentalcancel]').forEach(b=>b.onclick=()=>rentalState(b.dataset.rentalcancel,true));root.querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>{openModal('Reabrir sector','<p>Las clases afectadas se mantienen pendientes de reubicación hasta que las revises.</p>','<button id="reopen" class="primary">Reabrir sector</button>');$('#reopen').onclick=async e=>{if(await action('reopen',{closure_id:b.dataset.reopen},e.currentTarget)){$('#modal').close();toast('Sector abierto.')}}});root.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{const s=by('students',b.dataset.student);openModal(esc(s.name),`<div class="detailgrid"><div><small>Nivel</small><b>${s.level}</b></div><div><small>Nacimiento</small><b>${s.birth_date}</b></div></div><h3>Sus clases</h3>${classTable(data.classes.filter(c=>data.enrollments.some(e=>e.class_id===c.id&&e.student_id===s.id&&e.status==='confirmada')))}`)});root.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{const a=b.dataset.act;if(a==='menu'){$('.sidebar').classList.toggle('open');return}if(a==='logout'){logout();return}if(a==='refresh'){await load();toast('Agenda actualizada.');return}if(a==='newclass')classForm();if(a==='newgroup')classForm(null,'grupal');if(a==='newstudent')studentForm();if(a==='newrental')rentalForm();if(a==='prev'||a==='next'){const d=new Date(day+'T12:00Z');d.setUTCDate(d.getUTCDate()+(a==='prev'?-1:1));day=d.toISOString().slice(0,10);await load()}});if(root===document){$('#day')?.addEventListener('change',async e=>{day=e.target.value;await load()});$('#sportfilter')?.addEventListener('change',e=>{discipline=e.target.value;render()});$('#search')?.addEventListener('input',e=>{$('#studentrows').innerHTML=studentRows(e.target.value);bind($('#studentrows'))})}}
function logout(){if(!demo&&session)fetch(cfg.url+'/auth/v1/logout',{method:'POST',headers:{apikey:cfg.key,Authorization:'Bearer '+session.access_token}}).catch(()=>{});sessionStorage.removeItem('cota.session');session=null;profile=null;login()}
function login(){const config=!!cfg.url;$('#app').innerHTML=`<div class="login"><div class="brand">${logo}<div>COTA<small>ESCUELA DE NIEVE</small></div></div><h2>Ingresá a la operación</h2><p class="sub">Cada cuenta tiene su rol asignado por coordinación.</p>${config?`<form id="loginform"><div class="field"><label for="email">Cuenta</label><input id="email" type="email" autocomplete="username" required placeholder="nombre@cota.test"></div><div class="field"><label for="password">Contraseña</label><input id="password" type="password" autocomplete="current-password" required></div><button class="primary">Ingresar</button></form><div id="loginerror" class="validation" role="alert"></div>`:`<div class="validation">Supabase todavía no está conectado. La demostración usa una base local con datos sintéticos. Para el acceso real, configurá las variables del proyecto y creá las cuentas según el README.</div><button class="primary" id="backdemo">Volver a la demostración</button>`}<p class="sub" style="margin-top:25px">Sin registro público ni recuperación por correo.<br>Si no podés ingresar, hablá con coordinación.</p></div>`;$('#backdemo')?.addEventListener('click',()=>{profile={name:'Coordinación Demo',role:'coordinacion'};load()});$('#loginform')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const s=await rest('/auth/v1/token?grant_type=password',{email:$('#email').value,password:$('#password').value});session={...s,expires_at:Date.now()+s.expires_in*1000};sessionStorage.setItem('cota.session',JSON.stringify(session));await startReal()}catch(err){$('#loginerror').textContent=err.message}finally{b.disabled=false}})}
async function startReal(){const profiles=await rest('/rest/v1/profiles?id=eq.'+session.user.id+'&select=id,name,role');profile=profiles[0];if(!profile)throw Error('Tu cuenta no tiene un perfil habilitado. Consultá con coordinación.');await load()}
async function init(){if(!demo){try{session=JSON.parse(sessionStorage.getItem('cota.session'));if(session){await startReal();return}}catch{}login();return}try{const {PGlite}=await import('./vendor/index.js');db=await PGlite.create('idb://cota-demo-v6');const exists=await db.query("select to_regclass('public.profiles') as t");if(!exists.rows[0].t){for(const file of ['demo-bootstrap.sql','schema.sql','seed.sql','demo-profiles.sql'])await db.exec(await(await fetch('./'+file)).text())}await db.query("select set_config('request.jwt.claim.sub','00000000-0000-4000-0001-000000000001',false)");profile={name:'Coordinación Demo',role:'coordinacion'};await load()}catch(e){$('#app').innerHTML=`<div class="boot"><h1>COTA</h1><p>No pudimos abrir la demostración local.</p><p>${esc(e.message)}</p><button onclick="location.reload()">Volver a intentar</button></div>`}}
init();
